package love.onlyyours;
import android.app.*;
import android.content.*;
import android.media.*;
import android.net.Uri;
import android.os.Build;
import org.json.*;

/** Private notification text only; no message bodies, images or decryption keys. */
public final class LoveNotifications {
 public static volatile boolean chatVisible=false;
 private static final java.security.SecureRandom random=new java.security.SecureRandom();
 private static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("notification-state",0);}
 public static void channels(Context c){NotificationManager n=c.getSystemService(NotificationManager.class);for(String id:new String[]{"messages-v2","nudges-v1","incoming-calls-v1"}){boolean call=id.startsWith("incoming");NotificationChannel channel=new NotificationChannel(id,call?"Incoming calls":id.startsWith("nudges")?"Remember me nudges":"Messages",NotificationManager.IMPORTANCE_HIGH);channel.setLockscreenVisibility(Notification.VISIBILITY_PRIVATE);channel.enableVibration(true);channel.setVibrationPattern(call?new long[]{0,450,350,450}:id.startsWith("nudges")?new long[]{0,100,80,160}:new long[]{0,100});channel.setSound(call?android.provider.Settings.System.DEFAULT_RINGTONE_URI:android.provider.Settings.System.DEFAULT_NOTIFICATION_URI,new AudioAttributes.Builder().setUsage(call?AudioAttributes.USAGE_NOTIFICATION_RINGTONE:AudioAttributes.USAGE_NOTIFICATION).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());n.createNotificationChannel(channel);}}
 private static int id(String call){return 1000+(call.hashCode()&0x3fffffff);}
 private static PendingIntent open(Context c,int request){return PendingIntent.getActivity(c,request,new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
 private static boolean remember(Context c,String key){synchronized(LoveNotifications.class){android.content.SharedPreferences p=prefs(c);try{JSONArray seen=new JSONArray(p.getString("seen","[]"));for(int i=0;i<seen.length();i++)if(key.equals(seen.getString(i)))return false;JSONArray next=new JSONArray();for(int i=Math.max(0,seen.length()-511);i<seen.length();i++)next.put(seen.getString(i));next.put(key);p.edit().putString("seen",next.toString()).apply();return true;}catch(Exception e){return true;}}}
 public static void message(Context c,String messageId,boolean nudge){if(messageId==null||messageId.length()>80||!remember(c,"message:"+messageId))return;if(chatVisible&&!nudge)return;channels(c);Notification n=new Notification.Builder(c,nudge?"nudges-v1":"messages-v2").setSmallIcon(android.R.drawable.btn_star_big_on).setContentTitle("Only Yours").setContentText(nudge?"Remember me ♡ · Your person sent a nudge":"A new encrypted message is waiting ♡").setCategory(Notification.CATEGORY_MESSAGE).setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(open(c,18)).setAutoCancel(true).setOnlyAlertOnce(false).build();try{c.getSystemService(NotificationManager.class).notify(18,n);}catch(SecurityException ignored){}}
 private static PendingIntent callAction(Context c,String callId,String token,String action){Intent i=new Intent(c,MainActivity.class).setAction("love.onlyyours.call."+action).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP).putExtra("callId",callId).putExtra("callAction",action).putExtra("callNonce",token);return PendingIntent.getActivity(c,id(callId)+(action.equals("answer")?1:action.equals("decline")?2:3),i,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
 public static void incoming(Context c,String callId,boolean video,long at){if(callId==null||!callId.matches("[a-zA-Z0-9_-]{1,80}")||at+60000<=System.currentTimeMillis())return;android.content.SharedPreferences p=prefs(c);if(p.getLong("ended:"+callId,0)>System.currentTimeMillis()||p.getLong("handled:"+callId,0)>System.currentTimeMillis())return;if(CallService.state.isActive()&&!CallService.state.owns(callId))return;channels(c);String token=p.getString("nonce:"+callId,null);if(token==null){byte[] bytes=new byte[24];random.nextBytes(bytes);token=android.util.Base64.encodeToString(bytes,android.util.Base64.NO_WRAP);p.edit().putString("nonce:"+callId,token).apply();}PendingIntent answer=callAction(c,callId,token,"answer"),decline=callAction(c,callId,token,"decline"),view=callAction(c,callId,token,"open");Notification.Builder b=new Notification.Builder(c,"incoming-calls-v1").setSmallIcon(android.R.drawable.sym_call_incoming).setContentTitle(video?"Incoming video call":"Incoming voice call").setContentText("Your person · Only Yours").setCategory(Notification.CATEGORY_CALL).setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(view).setOngoing(true).setOnlyAlertOnce(true).setTimeoutAfter(Math.max(1000,at+60000-System.currentTimeMillis()));if(Build.VERSION.SDK_INT>=31)b.setStyle(Notification.CallStyle.forIncomingCall(new Person.Builder().setName("Your person").setImportant(true).build(),decline,answer).setIsVideo(video));else b.addAction(new Notification.Action.Builder(null,"Decline",decline).build()).addAction(new Notification.Action.Builder(null,"Answer",answer).build());NotificationManager nm=c.getSystemService(NotificationManager.class);if(Build.VERSION.SDK_INT<34||nm.canUseFullScreenIntent())b.setFullScreenIntent(view,true);try{Notification callNotification=b.build();callNotification.flags|=Notification.FLAG_INSISTENT;nm.notify("call:"+callId,id(callId),callNotification);}catch(SecurityException ignored){}}
 public static void clearCall(Context c,String callId){if(callId==null||callId.isEmpty())return;prefs(c).edit().putLong("ended:"+callId,System.currentTimeMillis()+90000).remove("nonce:"+callId).apply();c.getSystemService(NotificationManager.class).cancel("call:"+callId,id(callId));}
 public static boolean handleIntent(Context c,Intent intent){if(intent==null)return false;String callId=intent.getStringExtra("callId"),nonce=intent.getStringExtra("callNonce"),action=intent.getStringExtra("callAction");if(callId==null||nonce==null||(!"answer".equals(action)&&!"decline".equals(action)&&!"open".equals(action)))return false;android.content.SharedPreferences p=prefs(c);String expected=p.getString("nonce:"+callId,null);if(expected==null||!java.security.MessageDigest.isEqual(expected.getBytes(java.nio.charset.StandardCharsets.UTF_8),nonce.getBytes(java.nio.charset.StandardCharsets.UTF_8)))return false;try{String pending=new JSONObject().put("id",callId).put("action",action).put("at",System.currentTimeMillis()).toString();p.edit().putString("pending-action",pending).apply();if(!"open".equals(action)){p.edit().remove("nonce:"+callId).putLong("handled:"+callId,System.currentTimeMillis()+90000).apply();c.getSystemService(NotificationManager.class).cancel("call:"+callId,id(callId));}return true;}catch(Exception e){return false;}}
 public static String consumeAction(Context c){android.content.SharedPreferences p=prefs(c);String action=p.getString("pending-action","");p.edit().remove("pending-action").apply();return action;}
}
